// Every spoken line in the game. Audio files live in public/voice/<id>.mp3 (made by
// scripts/voice/generate.mjs, with a local voice model). If a file is missing the game shows the
// caption long enough to read instead.
//
// HOW TO WRITE A LINE (the Learn episodes; please keep to this for every new line)
// A line has two forms. `text` is what's shown on screen: digits and signs are fine there
// ("6 + 2 = 8"). `said` is what the voice reads out, for a 5-year-old who can't read yet:
//  - Whole sentences. "Hop 2: 8." is a fragment; say "Hop one more, to eight."
//  - Numbers as words: "twenty-four", "three hundred and five", "two forty" for 2:40.
//  - Signs as words: "plus", "take away", "times", "divided by", "minus" (for a negative number),
//    "percent", "dollars". "Equals" only in algebra; elsewhere "makes" or "is".
//  - No colons, no brackets, no slashes, no arrows. Fractions as words: "three quarters", "two sixths".
//  - No bare lists of numbers. A count is fine when the line says it's counting
//    ("Count by tens. Ten, twenty, thirty!").
//  - No capitals for stress (the voice can't shout one word): "just one", not "ONE".
//  - Short: one idea, one or two sentences, under about 25 words.
//  - Keep `text` and `said` the same sentence, so a child who reads along hears what's written.
// Leave `said` out only when the shown words already read well aloud (no digits, signs or colons);
// a test checks every Learn line's spoken form.

export type BuddyVoice = 'kid-a' | 'kid-b' | 'kid-c';
export type VoiceId = 'coach' | import('../art/cast').FriendId | BuddyVoice;
export type Line = { id: string; voice: VoiceId; text: string; /** what the voice reads, when it differs from the text shown */ said?: string };

const coach = (id: string, text: string): Line => ({ id, voice: 'coach', text });
/** A Learn line: shown words, and the spoken words (see the guide above). */
const ep = (id: string, text: string, said?: string): Line => ({ id, voice: 'coach', text, said: said ?? text });

